package com.swiftroute.orderservice.controller;
import java.util.*; import org.springframework.http.ResponseEntity; import org.springframework.web.bind.annotation.*; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor;
import com.swiftroute.orderservice.dto.request.*; import com.swiftroute.orderservice.dto.response.ApiResponse; import com.swiftroute.orderservice.service.ExceptionOperationsService;
@RestController @RequestMapping("/api/operations") @RequiredArgsConstructor public class ExceptionOperationsController {
 private final ExceptionOperationsService service; private UUID id(String value){return UUID.fromString(value);}
 @PostMapping("/orders/{orderId}/incidents") public ResponseEntity<ApiResponse<?>> incident(@PathVariable UUID orderId,@Valid @RequestBody CreateIncidentRequest body,@RequestHeader("X-Tenant-Id") String tenant,@RequestHeader("X-User-Id") String user,@RequestHeader("X-User-Role") String role){ return ResponseEntity.ok(ApiResponse.success(service.report(orderId,id(tenant),id(user),role,body.incidentType(),body.notes()))); }
 @PatchMapping("/incidents/{id}/resolve") public ResponseEntity<ApiResponse<?>> resolve(@PathVariable UUID id,@RequestBody Map<String,String> body,@RequestHeader("X-Tenant-Id") String tenant,@RequestHeader("X-User-Id") String user,@RequestHeader("X-User-Role") String role){ return ResponseEntity.ok(ApiResponse.success(service.resolve(id,this.id(tenant),this.id(user),role,body.get("notes")))); }
 @PostMapping("/orders/{orderId}/returns") public ResponseEntity<ApiResponse<?>> requestReturn(@PathVariable UUID orderId,@Valid @RequestBody CreateReturnRequest req,@RequestHeader("X-Tenant-Id") String tenant,@RequestHeader("X-User-Id") String user,@RequestHeader("X-User-Role") String role){ return ResponseEntity.ok(ApiResponse.success(service.requestReturn(orderId,id(tenant),id(user),role,req))); }
 @PatchMapping("/returns/{id}/approve") public ResponseEntity<ApiResponse<?>> approveReturn(@PathVariable UUID id,@RequestHeader("X-Tenant-Id") String tenant,@RequestHeader("X-User-Id") String user,@RequestHeader("X-User-Role") String role){ return ResponseEntity.ok(ApiResponse.success(service.approveReturn(id,this.id(tenant),this.id(user),role))); }
 @PatchMapping("/returns/{id}/confirm-receipt") public ResponseEntity<ApiResponse<?>> confirmReturnReceipt(@PathVariable UUID id,@RequestBody(required=false) ConfirmReturnReceiptRequest req,@RequestHeader("X-Tenant-Id") String tenant,@RequestHeader("X-User-Id") String user,@RequestHeader("X-User-Role") String role){ return ResponseEntity.ok(ApiResponse.success(service.confirmReturnReceipt(id,this.id(tenant),this.id(user),role,req==null?null:req.notes()))); }
 @PostMapping("/orders/{orderId}/cod-collections") public ResponseEntity<ApiResponse<?>> collect(@PathVariable UUID orderId,@Valid @RequestBody CollectCodRequest req,@RequestHeader("X-Tenant-Id") String tenant,@RequestHeader("X-User-Id") String user,@RequestHeader("X-User-Role") String role){ return ResponseEntity.ok(ApiResponse.success(service.collect(orderId,id(tenant),id(user),role,req))); }
 @PatchMapping("/cod-collections/{id}/declare") public ResponseEntity<ApiResponse<?>> declare(@PathVariable UUID id,@Valid @RequestBody CodHandoverRequest req,@RequestHeader("X-Tenant-Id") String tenant,@RequestHeader("X-User-Id") String user,@RequestHeader("X-User-Role") String role){ return ResponseEntity.ok(ApiResponse.success(service.declare(id,this.id(tenant),this.id(user),role,req))); }
 @GetMapping("/cod-collections/mine") public ResponseEntity<ApiResponse<?>> pendingHandover(@RequestHeader("X-Tenant-Id") String tenant,@RequestHeader("X-User-Id") String user,@RequestHeader("X-User-Role") String role){ return ResponseEntity.ok(ApiResponse.success(service.pendingHandover(id(tenant),id(user),role))); }
 @PatchMapping("/cod-collections/{id}/verify") public ResponseEntity<ApiResponse<?>> verify(@PathVariable UUID id,@RequestBody Map<String,String> body,@RequestHeader("X-Tenant-Id") String tenant,@RequestHeader("X-User-Id") String user,@RequestHeader("X-User-Role") String role){ return ResponseEntity.ok(ApiResponse.success(service.verify(id,this.id(tenant),this.id(user),role,body.get("notes")))); }
 @GetMapping("/review") public ResponseEntity<ApiResponse<?>> review(@RequestHeader("X-Tenant-Id") String tenant,@RequestHeader("X-User-Role") String role){ return ResponseEntity.ok(ApiResponse.success(service.review(id(tenant),role))); }
}
